#define MAXN 15
#define MAXM 15

int r, c, k;
int grid[MAXN][MAXM];
int prefix[MAXN+1][MAXM+1];

int get_sum(int r1, int c1, int r2, int c2) {
    return prefix[r2+1][c2+1] - prefix[r1][c2+1] - prefix[r2+1][c1] + prefix[r1][c1];
}

typedef struct {
    int groups;
    int max_demand;
} Result;

Result best;

Result max(Result a, Result b) {
    if (a.groups > b.groups) return a;
    if (a.groups < b.groups) return b;
    if (a.max_demand < b.max_demand) return a;
    return b;
}

Result solve(int r1, int c1, int r2, int c2) {
    int total = get_sum(r1, c1, r2, c2);
    Result res = {1, total};

    if (r1 == r2 && c1 == c2) return res;

    // Try horizontal cuts
    for (int cut = r1; cut < r2; cut++) {
        int top_sum = get_sum(r1, c1, cut, c2);
        int bottom_sum = get_sum(cut+1, c1, r2, c2);
        if (top_sum <= k && bottom_sum <= k) {
            Result top_res = solve(r1, c1, cut, c2);
            Result bottom_res = solve(cut+1, c1, r2, c2);
            Result combined;
            combined.groups = top_res.groups + bottom_res.groups;
            combined.max_demand = (top_res.max_demand > bottom_res.max_demand) ? 
                                  top_res.max_demand : bottom_res.max_demand;
            res = max(res, combined);
        }
    }

    // Try vertical cuts
    for (int cut = c1; cut < c2; cut++) {
        int left_sum = get_sum(r1, c1, r2, cut);
        int right_sum = get_sum(r1, cut+1, r2, c2);
        if (left_sum <= k && right_sum <= k) {
            Result left_res = solve(r1, c1, r2, cut);
            Result right_res = solve(r1, cut+1, r2, c2);
            Result combined;
            combined.groups = left_res.groups + right_res.groups;
            combined.max_demand = (left_res.max_demand > right_res.max_demand) ? 
                                  left_res.max_demand : right_res.max_demand;
            res = max(res, combined);
        }
    }

    return res;
}

