typedef struct {
    short r, h, c, w;
    int sum;
    int area;
} Rect;

typedef struct {
    int groups;
    int kept;
    char vis;
} State;

static int H, W, Ccap;
static int *pref = NULL;
static Rect *rects = NULL;
static int rectCount = 0;
static int ****idmap = NULL; /* unused */

static State *memo = NULL;

static inline int max(int a, int b){ return a>b?a:b; }

static int rect_sum(int r, int h, int c, int w) {
    int r2 = r + h;
    int c2 = c + w;
    return pref[r2*(W+1)+c2] - pref[r*(W+1)+c2] - pref[r2*(W+1)+c] + pref[r*(W+1)+c];
}

static int rect_id(int r, int h, int c, int w) {
    // enumerate rectangles in fixed order:
    // id = sum over h'<h, w'<... not trivial; use direct search avoided by precomputed table.
    // We'll store in 4D flattened sparse via formula:
    // (((r*(H+1)+h)*(W)+c)*(W+1)+w) impossible because ranges vary but okay enough if allocated?
    return (((r*(H+1) + h) * W + c) * (W+1) + w);
}

static inline State *get_state(int rid, int b) {
    return &memo[(long long)rid * (Ccap + 1) + b];
}

static State solve(int rid, int budget) {
    State *ms = get_state(rid, budget);
    if (ms->vis) return *ms;
    ms->vis = 1;

    Rect R = rects[rid];

    // No split
    ms->groups = 1;
    ms->kept = R.sum;

    // Horizontal splits
    for (int cut = 1; cut < R.h; ++cut) {
        int ridA = rect_id(R.r, cut, R.c, R.w);
        int ridB = rect_id(R.r + cut, R.h - cut, R.c, R.w);
        Rect A = rects[ridA], B = rects[ridB];

        // Keep in A, suppress all of B
        if (budget >= B.sum) {
            State sa = solve(ridA, budget - B.sum);
            int g = sa.groups + B.area;
            int k = sa.kept;
            if (g > ms->groups || (g == ms->groups && k > ms->kept)) {
                ms->groups = g;
                ms->kept = k;
            }
        }
        // Keep in B, suppress all of A
        if (budget >= A.sum) {
            State sb = solve(ridB, budget - A.sum);
            int g = sb.groups + A.area;
            int k = sb.kept;
            if (g > ms->groups || (g == ms->groups && k > ms->kept)) {
                ms->groups = g;
                ms->kept = k;
            }
        }
    }

    // Vertical splits
    for (int cut = 1; cut < R.w; ++cut) {
        int ridA = rect_id(R.r, R.h, R.c, cut);
        int ridB = rect_id(R.r, R.h, R.c + cut, R.w - cut);
        Rect A = rects[ridA], B = rects[ridB];

        if (budget >= B.sum) {
            State sa = solve(ridA, budget - B.sum);
            int g = sa.groups + B.area;
            int k = sa.kept;
            if (g > ms->groups || (g == ms->groups && k > ms->kept)) {
                ms->groups = g;
                ms->kept = k;
            }
        }
        if (budget >= A.sum) {
            State sb = solve(ridB, budget - A.sum);
            int g = sb.groups + A.area;
            int k = sb.kept;
            if (g > ms->groups || (g == ms->groups && k > ms->kept)) {
                ms->groups = g;
                ms->kept = k;
            }
        }
    }

    return *ms;
}

