long long sumRect(int r1, int c1, int r2, int c2) {
    return pref[r2+1][c2+1] - pref[r1][c2+1] - pref[r2+1][c1] + pref[r1][c1];
}

struct Sol {
    int groups;
    long long maxSuppressed;
    bool valid;
};

Sol solve(int r1, int c1, int r2, int c2) {
    long long total = sumRect(r1, c1, r2, c2);
    if (total <= K) {
        // can be one group (the unsuppressed one)
        return {1, total, true};
    }
    // need to split
    int bestGroups = -1;
    long long bestMaxSupp = -1;
    bool possible = false;

    // try horizontal cuts
    for (int r = r1; r < r2; r++) {
        long long top = sumRect(r1, c1, r, c2);
        long long bottom = sumRect(r+1, c1, r2, c2);
        if (top <= K && bottom <= K) {
            Sol leftSol = solve(r1, c1, r, c2);
            Sol rightSol = solve(r+1, c1, r2, c2);
            if (leftSol.valid && rightSol.valid) {
                int totalGroups = leftSol.groups + rightSol.groups;
                long long maxSupp = max(leftSol.maxSuppressed, rightSol.maxSuppressed);
                if (totalGroups > bestGroups || (totalGroups == bestGroups && maxSupp > bestMaxSupp)) {
                    bestGroups = totalGroups;
                    bestMaxSupp = maxSupp;
                    possible = true;
                }
            }
        } else if (top <= K) {
            Sol leftSol = solve(r1, c1, r, c2);
            if (leftSol.valid) {
                long long bottomSupp = bottom;
                int totalGroups = leftSol.groups + 1;
                long long maxSupp = max(leftSol.maxSuppressed, bottomSupp);
                if (totalGroups > bestGroups || (totalGroups == bestGroups && maxSupp > bestMaxSupp)) {
                    bestGroups = totalGroups;
                    bestMaxSupp = maxSupp;
                    possible = true;
                }
            }
        } else if (bottom <= K) {
            Sol rightSol = solve(r+1, c1, r2, c2);
            if (rightSol.valid) {
                long long topSupp = top;
                int totalGroups = 1 + rightSol.groups;
                long long maxSupp = max(topSupp, rightSol.maxSuppressed);
                if (totalGroups > bestGroups || (totalGroups == bestGroups && maxSupp > bestMaxSupp)) {
                    bestGroups = totalGroups;
                    bestMaxSupp = maxSupp;
                    possible = true;
                }
            }
        }
    }

    // try vertical cuts
    for (int c = c1; c < c2; c++) {
        long long left = sumRect(r1, c1, r2, c);
        long long right = sumRect(r1, c+1, r2, c2);
        if (left <= K && right <= K) {
            Sol leftSol = solve(r1, c1, r2, c);
            Sol rightSol = solve(r1, c+1, r2, c2);
            if (leftSol.valid && rightSol.valid) {
                int totalGroups = leftSol.groups + rightSol.groups;
                long long maxSupp = max(leftSol.maxSuppressed, rightSol.maxSuppressed);
                if (totalGroups > bestGroups || (totalGroups == bestGroups && maxSupp > bestMaxSupp)) {
                    bestGroups = totalGroups;
                    bestMaxSupp = maxSupp;
                    possible = true;
                }
            }
        } else if (left <= K) {
            Sol leftSol = solve(r1, c1, r2, c);
            if (leftSol.valid) {
                long long rightSupp = right;
                int totalGroups = leftSol.groups + 1;
                long long maxSupp = max(leftSol.maxSuppressed, rightSupp);
                if (totalGroups > bestGroups || (totalGroups == bestGroups && maxSupp > bestMaxSupp)) {
                    bestGroups = totalGroups;
                    bestMaxSupp = maxSupp;
                    possible = true;
                }
            }
        } else if (right <= K) {
            Sol rightSol = solve(r1, c+1, r2, c2);
            if (rightSol.valid) {
                long long leftSupp = left;
                int totalGroups = 1 + rightSol.groups;
                long long maxSupp = max(leftSupp, rightSol.maxSuppressed);
                if (totalGroups > bestGroups || (totalGroups == bestGroups && maxSupp > bestMaxSupp)) {
                    bestGroups = totalGroups;
                    bestMaxSupp = maxSupp;
                    possible = true;
                }
            }
        }
    }

    if (!possible) return {0, 0, false};
    return {bestGroups, bestMaxSupp, true};
}

