#include <bits/stdc++.h>
using namespace std;

struct Best {
    int groups;          // maximum number of groups
    long long sum;       // maximum suppressible demand among optimal groupings
    Best(int g = -1, long long s = -1) : groups(g), sum(s) {}
};

static inline bool better(const Best& a, const Best& b) {
    if (a.groups != b.groups) return a.groups > b.groups;
    return a.sum > b.sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H;
    long long C;
    cin >> W >> H >> C;

    vector<vector<long long>> a(H + 1, vector<long long>(W + 1, 0));
    for (int y = 1; y <= H; ++y) {
        for (int x = 1; x <= W; ++x) {
            cin >> a[y][x];
        }
    }

    // Prefix sums
    vector<vector<long long>> ps(H + 1, vector<long long>(W + 1, 0));
    for (int y = 1; y <= H; ++y) {
        for (int x = 1; x <= W; ++x) {
            ps[y][x] = a[y][x] + ps[y-1][x] + ps[y][x-1] - ps[y-1][x-1];
        }
    }

    auto rectSum = [&](int x1, int y1, int x2, int y2) -> long long {
        return ps[y2][x2] - ps[y1-1][x2] - ps[y2][x1-1] + ps[y1-1][x1-1];
    };

    // dp[x1][y1][x2][y2]
    // Because dimensions are small enough in intended problem, use map by encoded rectangle.
    // We compute by increasing size.
    int maxW = W, maxH = H;

    // 4D flattened storage
    auto id = [&](int x1, int y1, int x2, int y2) {
        // all 1-based inclusive
        long long res = x1;
        res = res * (H + 1) + y1;
        res = res * (W + 1) + x2;
        res = res * (H + 1) + y2;
        return (size_t)res;
    };

    size_t totalStates = (size_t)(W + 1) * (H + 1) * (W + 1) * (H + 1);
    vector<Best> dp(totalStates, Best());

    for (int w = 1; w <= W; ++w) {
        for (int h = 1; h <= H; ++h) {
            for (int x1 = 1; x1 + w - 1 <= W; ++x1) {
                int x2 = x1 + w - 1;
                for (int y1 = 1; y1 + h - 1 <= H; ++y1) {
                    int y2 = y1 + h - 1;
                    long long s = rectSum(x1, y1, x2, y2);

                    Best cur;
                    if (s <= C) cur = Best(1, s); // keep this whole rectangle as one suppressible group

                    // vertical splits
                    for (int xm = x1; xm < x2; ++xm) {
                        Best L = dp[id(x1, y1, xm, y2)];
                        Best R = dp[id(xm + 1, y1, x2, y2)];
                        if (L.groups == -1 || R.groups == -1) continue;
                        Best cand(L.groups + R.groups, L.sum + R.sum);
                        if (better(cand, cur)) cur = cand;
                    }

                    // horizontal splits
                    for (int ym = y1; ym < y2; ++ym) {
                        Best U = dp[id(x1, y1, x2, ym)];
                        Best D = dp[id(x1, ym + 1, x2, y2)];
                        if (U.groups == -1 || D.groups == -1) continue;
                        Best cand(U.groups + D.groups, U.sum + D.sum);
                        if (better(cand, cur)) cur = cand;
                    }

                    dp[id(x1, y1, x2, y2)] = cur;
                }
            }
        }
    }

    Best ans = dp[id(1, 1, W, H)];

    // The chosen blackout plan suppresses ans.sum demand.
    // Reserve power = C - ans.sum.
    cout << ans.groups << " " << (C - ans.sum) << "\n";
    return 0;
}

