    // Redesigned approach with tracking suppressed count
    static List<int[]> solve3(int r1, int c1, int r2, int c2, Map<String, List<int[]>> memo3) {
        String key = r1 + "," + c1 + "," + r2 + "," + c2;
        if (memo3.containsKey(key)) return memo3.get(key);

        List<int[]> result = new ArrayList<>();
        int total = getSum(r1, c1, r2, c2);
        // (groups, maxSuppressedDemand) where suppressedDemand is demand of the group that may exceed supply
        // but only one such group allowed overall

