        result.add(new int[]{1, total});

        // horizontal splits
        for (int r = r1; r < r2; r++) {
            List<int[]> top = solve3(r1, c1, r, c2, memo3);
            List<int[]> bottom = solve3(r + 1, c1, r2, c2, memo3);
            for (int[] a : top) {
                for (int[] b : bottom) {
                    int supCount = 0;
                    int maxSup = 0;
                    if (a[1] > supply) { supCount++; maxSup = Math.max(maxSup, a[1]); }
                    if (b[1] > supply) { supCount++; maxSup = Math.max(maxSup, b[1]); }
                    if (supCount <= 1) {
                        result.add(new int[]{a[0] + b[0], maxSup});
                    }
                }
            }
        }

        // vertical splits
        for (int c = c1; c < c2; c++) {
            List<int[]> left = solve3(r1, c1, r2, c, memo3);
            List<int[]> right = solve3(r1, c + 1, r2, c2, memo3);
            for (int[] a : left) {
                for (int[] b : right) {
                    int supCount = 0;
                    int maxSup = 0;
                    if (a[1] > supply) { supCount++; maxSup = Math.max(maxSup, a[1]); }
                    if (b[1] > supply) { supCount++; maxSup = Math.max(maxSup, b[1]); }
                    if (supCount <= 1) {
                        result.add(new int[]{a[0] + b[0], maxSup});
                    }
                }
            }
        }

        memo3.put(key, result);
        return result;
    }

    static int getSum(int r1, int c1, int r2, int c2) {
        return prefix[r2 + 1][c2 + 1] - prefix[r1][c2 + 1] - prefix[r2 + 1][c1] + prefix[r1][c1];
    }
