    static Map<Long, long[]> memo = new HashMap<>();

    static long rectSum(int r1, int c1, int r2, int c2) {
        return prefix[r2][c2] - prefix[r1][c2] - prefix[r2][c1] + prefix[r1][c1];
    }

    // returns [groups, reserve*-1 (to minimize for max), totalDemand, maxGroup]
    // We store [groups, reserve, totalDemand, maxGroup]
    static long[] solve(int r1, int c1, int r2, int c2) {
        long key = ((long)r1*1001*1001*1001) + ((long)c1*1001*1001) + ((long)r2*1001) + c2;
        if (memo.containsKey(key)) return memo.get(key);
        long total = rectSum(r1, c1, r2, c2);
        long[] best = new long[]{1, supply - total, total, total};
        for (int r = r1+1; r < r2; r++) {
            long[] L = solve(r1,c1,r,c2), Ri = solve(r,c1,r2,c2);
            long[] cand = combine(L, Ri);
            if (better(cand, best)) best = cand;
        }
        for (int c = c1+1; c < c2; c++) {
            long[] L = solve(r1,c1,r2,c), Ri = solve(r1,c,r2,c2);
            long[] cand = combine(L, Ri);
            if (better(cand, best)) best = cand;
        }
        memo.put(key, best);
        return best;
    }

    static long[] combine(long[] L, long[] R) {
        long groups = L[0] + R[0];
        long total = L[2] + R[2];
