/*
We have an h x w grid of nonnegative demands.
A "grouping" is obtained by recursively splitting rectangles horizontally/vertically.
Exactly one final group remains powered; all other final groups are suppressed.
Let total demand be S, powered group's demand be x.
Then suppressed demand = S - x, which must be <= C.
Equivalent: powered group demand x >= S - C.

We want:
1) maximize number of final groups,
2) among those, maximize reserve = C - suppressed = C - (S - x) = x - (S - C),
   i.e. maximize powered group's demand x.

DP on rectangles:
For each rectangle R, compute all achievable pairs (k, bestKeepSum):
- k = number of final groups inside R
- bestKeepSum = maximum demand of the one powered final group among all valid partitions of R into k groups.

Base: rectangle itself as one group => (1, sum(R)).

Transition:
Split R into A and B.
To keep exactly one powered group overall, one side must be entirely suppressed, the other side must be a valid partition with one powered group.
If side A contributes (kA, keepA), then all groups in B are suppressed, so total suppressed demand:
   (sumA - keepA) + sumB = sumR - keepA
Need <= C => keepA >= sumR - C.
Then total groups = kA + 1, powered sum = keepA.
Similarly using B as active side.

Thus for each split, states from one side can generate states for parent.

Finally answer for whole grid: choose maximum k achievable; among them maximum keepSum.
Reserve = C - (total - keepSum).

Complexity:
Number of rectangles O(H^2 W^2), each has O(H+W) splits.
For each rectangle we store only nondominated states by k (best keepSum per k).
Suitable for small/medium constraints typical for rectangle DP.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static int H, W;
    static long C;
    static long[][] pref;

    // dp[r1][r2][c1][c2] compressed by hashmap key
    static HashMap<Long, long[]> memo = new HashMap<>();

    static long rectSum(int r1, int r2, int c1, int c2) {
        return pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] - pref[r2 + 1][c1] + pref[r1][c1];
    }

    static long key(int r1, int r2, int c1, int c2) {
        long k = r1;
        k = k * 35 + r2;
        k = k * 35 + c1;
        k = k * 35 + c2;
        return k;
    }

    static long[] solve(int r1, int r2, int c1, int c2) {
        long k = key(r1, r2, c1, c2);
        long[] got = memo.get(k);
        if (got != null) return got;

        long sum = rectSum(r1, r2, c1, c2);
        int area = (r2 - r1 + 1) * (c2 - c1 + 1);

        // bestKeep[g] = maximum keep sum for g groups, -1 if impossible
        long[] best = new long[area + 1];
        Arrays.fill(best, -1);
        best[1] = sum;

        // horizontal splits
        for (int rm = r1; rm < r2; rm++) {
            long[] top = solve(r1, rm, c1, c2);
            long[] bot = solve(rm + 1, r2, c1, c2);
            long sumTop = rectSum(r1, rm, c1, c2);
            long sumBot = sum - sumTop;

            for (int g = 1; g < top.length; g++) {
                long keep = top[g];
                if (keep < 0) continue;
                if (sum - keep <= C) {
                    int ng = g + 1;
                    if (keep > best[ng]) best[ng] = keep;
                }
            }
            for (int g = 1; g < bot.length; g++) {
                long keep = bot[g];
                if (keep < 0) continue;
                if (sum - keep <= C) {
                    int ng = g + 1;
                    if (keep > best[ng]) best[ng] = keep;
                }
            }
        }

        // vertical splits
        for (int cm = c1; cm < c2; cm++) {
            long[] left = solve(r1, r2, c1, cm);
            long[] right = solve(r1, r2, cm + 1, c2);
            long sumLeft = rectSum(r1, r2, c1, cm);
            long sumRight = sum - sumLeft;

            for (int g = 1; g < left.length; g++) {
                long keep = left[g];
                if (keep < 0) continue;
                if (sum - keep <= C) {
                    int ng = g + 1;
                    if (keep > best[ng]) best[ng] = keep;
                }
            }
            for (int g = 1; g < right.length; g++) {
                long keep = right[g];
                if (keep < 0) continue;
                if (sum - keep <= C) {
                    int ng = g + 1;
                    if (keep > best[ng]) best[ng] = keep;
                }
            }
        }

        memo.put(k, best);
        return best;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        H = fs.nextInt();
        W = fs.nextInt();
        C = fs.nextLong();

        long[][] a = new long[H][W];
        pref = new long[H + 1][W + 1];
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                a[i][j] = fs.nextLong();
                pref[i + 1][j + 1] = pref[i + 1][j] + pref[i][j + 1] - pref[i][j] + a[i][j];
            }
        }

        long total = rectSum(0, H - 1, 0, W - 1);
        long[] ans = solve(0, H - 1, 0, W - 1);

        int bestGroups = 0;
        long bestKeep = -1;
        for (int g = ans.length - 1; g >= 1; g--) {
            if (ans[g] >= 0) {
                bestGroups = g;
                bestKeep = ans[g];
                break;
            }
        }

        long reserve = C - (total - bestKeep);
        System.out.println(bestGroups + " " + reserve);
    }
